function buildResearchRequest(question) {
  if (typeof question !== "string" || !question.trim()) throw Error("Enter a research question.");
  return {
    model: "jina-deepsearch-v1",
    reasoning_effort: "low",
    stream: true,
    messages: [
      {
        role: "user",
        content:
          "Produce a clear, factual research report in Markdown. Cite the sources that support the main findings.",
      },
      { role: "assistant", content: "What would you like to research?" },
      { role: "user", content: question },
    ],
  };
}
return [
  {
    json: { request: buildResearchRequest($input.first().json.chatInput) },
    pairedItem: { item: 0 },
  },
];

function completedResearchReport(body) {
  if (typeof body !== "string" || !body.trim())
    throw Error("Jina did not return a completed research stream.");
  const annotations = new Map();
  const fragments = [];
  let stopped = false;
  let reasoningEnded = false;
  const events = body.replace(/\r\n?/g, "\n").split(/\n{2,}/);
  events.pop();
  for (const event of events) {
    const lines = event.split("\n");
    if (lines.some((line) => /^event:\s*error\s*$/i.test(line)))
      throw Error("Jina could not complete the research.");
    const data = lines
      .filter((line) => line.startsWith("data:"))
      .map((line) => line.slice(5).replace(/^ /, ""))
      .join("\n");
    if (!data.trim()) continue;
    if (data.trim() === "[DONE]") break;
    let packet;
    try {
      packet = JSON.parse(data);
    } catch {
      throw Error("Jina returned an unreadable research event.");
    }
    if (packet?.error) throw Error("Jina could not complete the research.");
    const choice = Array.isArray(packet?.choices)
      ? packet.choices.find((x) => (x?.index ?? 0) === 0)
      : null;
    if (!choice) continue;
    const { delta = {}, finish_reason: reason } = choice;
    if (delta.type === "error" || (reason && !["stop", "thinking_end"].includes(reason))) {
      throw Error("Jina could not complete the research.");
    }
    if (reason === "thinking_end") reasoningEnded = true;
    const visible = delta.type === "text" || (!delta.type && reasoningEnded);
    if (!stopped && visible && typeof delta.content === "string") fragments.push(delta.content);
    if (!stopped && visible && Array.isArray(delta.annotations)) {
      for (const { type, url_citation: citation } of delta.annotations.filter(
        (value) => value && typeof value === "object",
      )) {
        const url = citation?.url;
        if (
          type === "url_citation" &&
          typeof url === "string" &&
          /^https?:\/\/[^\s<>"\\]+$/i.test(url) &&
          !annotations.has(url)
        ) {
          const title =
            typeof citation.title === "string"
              ? citation.title
                  .trim()
                  .replace(/\s+/g, " ")
                  .replace(/[<>&]/g, "")
                  .replace(/[\\[\]]/g, "\\$&")
              : "";
          annotations.set(url, title);
        }
      }
    }
    if (reason === "stop" && delta.type !== "think") stopped = true;
  }
  const answer = fragments.join("").trim();
  if (!stopped || !answer) throw Error("Jina did not return a completed research report.");
  const sources = [...annotations]
    .filter(([url]) => !answer.includes(url))
    .map(([url, title]) => (title ? "- [" + title + "](<" + url + ">)" : "- <" + url + ">"));
  return sources.length ? answer + "\n\n### Sources\n\n" + sources.join("\n") : answer;
}
const { data, headers, statusCode } = $input.first().json;
if (
  statusCode !== 200 ||
  !/^text\/event-stream(?:;|$)/i.test(String(headers?.["content-type"] ?? ""))
) {
  throw Error("Jina did not return a successful research stream.");
}
return [{ json: { output: completedResearchReport(data) }, pairedItem: { item: 0 } }];
